// Cannapedia client-side search.
// Loads /search-index.json (generated by build.py) once, then filters
// in-browser as the user types. Small enough to not need a real search
// service yet -- swap this for something like Pagefind, Meilisearch, or
// Algolia later without touching the rest of the site.

(function () {
  var input = document.getElementById("cp-search-input");
  var resultsBox = document.getElementById("cp-search-results");
  var randomLinks = [
    document.getElementById("cp-random-link"),
    document.getElementById("cp-random-link-2"),
  ].filter(Boolean);

  var indexPromise = fetch("/search-index.json")
    .then(function (r) { return r.json(); })
    .catch(function () { return []; });

  function renderResults(matches, query) {
    resultsBox.innerHTML = "";
    if (!query) {
      resultsBox.hidden = true;
      return;
    }
    if (matches.length === 0) {
      var none = document.createElement("div");
      none.className = "cp-no-results";
      none.textContent = 'No articles match "' + query + '"';
      resultsBox.appendChild(none);
      resultsBox.hidden = false;
      return;
    }
    matches.slice(0, 8).forEach(function (m) {
      var a = document.createElement("a");
      a.href = m.url;
      var title = document.createElement("span");
      title.className = "cp-result-title";
      title.textContent = m.title;
      var desc = document.createElement("span");
      desc.className = "cp-result-desc";
      desc.textContent = m.short_description || "";
      a.appendChild(title);
      a.appendChild(desc);
      resultsBox.appendChild(a);
    });
    resultsBox.hidden = false;
  }

  function search(query, items) {
    var q = query.trim().toLowerCase();
    if (!q) return [];
    return items
      .map(function (item) {
        var titleIdx = item.title.toLowerCase().indexOf(q);
        var descIdx = (item.short_description || "").toLowerCase().indexOf(q);
        var bodyIdx = (item.text || "").toLowerCase().indexOf(q);
        var score = -1;
        if (titleIdx !== -1) score = 100 - titleIdx;
        else if (descIdx !== -1) score = 50 - descIdx;
        else if (bodyIdx !== -1) score = 10;
        return { item: item, score: score };
      })
      .filter(function (r) { return r.score > -1; })
      .sort(function (a, b) { return b.score - a.score; })
      .map(function (r) { return r.item; });
  }

  if (input) {
    indexPromise.then(function (items) {
      input.addEventListener("input", function () {
        var matches = search(input.value, items);
        renderResults(matches, input.value.trim());
      });
      input.addEventListener("keydown", function (e) {
        if (e.key === "Enter") {
          var matches = search(input.value, items);
          if (matches.length > 0) window.location.href = matches[0].url;
        }
        if (e.key === "Escape") {
          resultsBox.hidden = true;
        }
      });
      document.addEventListener("click", function (e) {
        if (!resultsBox.contains(e.target) && e.target !== input) {
          resultsBox.hidden = true;
        }
      });
    });
  }

  randomLinks.forEach(function (link) {
    link.addEventListener("click", function (e) {
      e.preventDefault();
      indexPromise.then(function (items) {
        if (items.length === 0) return;
        var pick = items[Math.floor(Math.random() * items.length)];
        window.location.href = pick.url;
      });
    });
  });
})();
